// src/core/root-config/root-config.schemas.ts
import { z } from 'zod';

export const updateRootConfigSchema = z.object({
  countryId: z.string().uuid('ID do país inválido').nullable().optional(),
  stateId: z.string().uuid('ID do estado inválido').nullable().optional(),
  cityId: z.string().uuid('ID da cidade inválida').nullable().optional(),
  timezone: z.string().max(100, 'Timezone deve ter no máximo 100 caracteres').nullable().optional(),
  currency: z.string().length(3, 'Moeda deve ter 3 caracteres (ISO 4217)').nullable().optional(),
  languages: z.array(z.string().min(2).max(10, 'Código de idioma inválido')).optional(),
});

export const setRegionSchema = z.object({
  countryId: z.string().uuid('ID do país inválido').nullable().optional(),
  stateId: z.string().uuid('ID do estado inválido').nullable().optional(),
  cityId: z.string().uuid('ID da cidade inválida').nullable().optional(),
});

export const setLanguagesSchema = z.object({
  languages: z.array(z.string().min(2).max(10, 'Código de idioma inválido')).min(1, 'Pelo menos um idioma é obrigatório'),
});

export const setTimezoneSchema = z.object({
  timezone: z.string().max(100, 'Timezone deve ter no máximo 100 caracteres').min(1, 'Timezone é obrigatório'),
});

export const setCurrencySchema = z.object({
  currency: z.string().length(3, 'Moeda deve ter 3 caracteres (ISO 4217)').min(1, 'Moeda é obrigatória'),
});
















